window.HISTORY_QUESTIONS = [{"id":1,"question":"Bối cảnh lịch sử nào sau đây dẫn đến sự hình thành Liên hợp quốc?","options":{"A":"Liên Xô và Mỹ thực hiện Chiến tranh lạnh.","B":"Chiến tranh thế giới thứ hai bắt đầu diễn ra ác liệt.","C":"Nhu cầu xác lập một tổ chức quốc tế nhằm duy trì hòa bình và trật tự thế giới sau chiến tranh.","D":"Các nước thắng trận trong chiến tranh thế giới thứ nhất phân chia phạm vi ảnh hưởng trên toàn cầu."},"answer":"C"},{"id":2,"question":"Nội dung nào sau đây là biểu hiện của xu thế đa cực?","options":{"A":"Các trung tâm quyền lực vươn lên, khẳng định sức mạnh về kinh tế, quân sự, chính trị đối với thế giới.","B":"Các nước tăng cường chạy đua về kinh tế và quân sự, hình thành các liên minh xuyên lục địa.","C":"Sự lớn mạnh của Trung Quốc trước cải cách, mở cửa, đe doạ đến vị trí số 1 của Mỹ.","D":"Các nước trong khối NATO liên kết với nhau tạo ra sức mạnh quân sự vượt trội."},"answer":"A"},{"id":3,"question":"Sự kiện nào sau đây năm 1941 là cơ sở cho việc hướng tới thành lập Liên hợp quốc?","options":{"A":"Tại Luân Đôn (Anh), các nước Đồng minh ra bản tuyên bố cam kết cùng hợp tác cả trong chiến tranh và hòa bình.","B":"Tại hội nghị I-an-ta, Liên Xô, Mỹ, Anh thống nhất thành lập tổ chức Liên hợp quốc.","C":"Tại hội nghị Tê-hê-ran (I-ran) nguyên thủ các nước khẳng định quyết tâm thành lập một tổ chức quốc tế để duy trì hòa bình và an ninh.","D":"Tại Mát-xcơ-va (Liên Xô), chính phủ Liên Xô, Mỹ, Anh, Trung Hoa Dân Quốc kêu gọi sớm thành lập một tổ chức quốc tế để duy trì hòa bình và an ninh."},"answer":"A"},{"id":4,"question":"Sự kiện nào sau đây đánh dấu việc Liên hợp quốc chính thức được thành lập?","options":{"A":"Tháng 1/1942 đại diện các nước: Mỹ, Anh, Liên Xô, Trung Quốc và 22 nước khác ký bản tuyên bố Liên hợp quốc.","B":"Từ tháng 4 đến tháng 6 năm 1945 đại diện 50 nước thông qua Hiến chương Liên hợp quốc.","C":"Ngày 24/10/1945 các nước thành viên phê chuẩn Hiến chương Liên hợp quốc.","D":"Tháng 2 năm 1945, Liên Xô, Mỹ, Anh thống nhất thành lập Liên hợp quốc."},"answer":"C"},{"id":5,"question":"Đọc đoạn tư liệu sau: \"Duy trì hoà bình và an ninh quốc tế, và để đạt được mục đích đó, thi hành những biện pháp tập thể có hiệu quả để phòng ngừa và loại trừ các mối đe doạ hoà bình, cấm mọi hành vi xâm lược và phá hoại hoà bình khác, điều chỉnh hoặc giải quyết các vụ tranh chấp hoặc những tình thế có tính chất quốc tế có thể đưa đến sự phá hoại hoà bình, bằng biện pháp hoà bình theo đúng nguyên tắc của công lí và pháp luật quốc tế.\" (Trích: Điều 1, Hiến chương Liên hợp quốc, ngày 24-10-1945)\n\nNhận định sau đúng hay sai? Đoạn tư liệu thể hiện mục tiêu của Liên hợp quốc là duy trì hoà bình và an ninh quốc phòng cho tất cả các quốc gia.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":6,"question":"Đọc đoạn tư liệu sau: \"Duy trì hoà bình và an ninh quốc tế, và để đạt được mục đích đó, thi hành những biện pháp tập thể có hiệu quả để phòng ngừa và loại trừ các mối đe doạ hoà bình, cấm mọi hành vi xâm lược và phá hoại hoà bình khác, điều chỉnh hoặc giải quyết các vụ tranh chấp hoặc những tình thế có tính chất quốc tế có thể đưa đến sự phá hoại hoà bình, bằng biện pháp hoà bình theo đúng nguyên tắc của công lí và pháp luật quốc tế.\" (Trích: Điều 1, Hiến chương Liên hợp quốc, ngày 24-10-1945)\n\nNhận định sau đúng hay sai? Một trong những mục tiêu của Liên hợp quốc là giải quyết các vụ tranh chấp quốc tế bằng pháp luật của các quốc gia.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":7,"question":"Đọc đoạn tư liệu sau: \"Duy trì hoà bình và an ninh quốc tế, và để đạt được mục đích đó, thi hành những biện pháp tập thể có hiệu quả để phòng ngừa và loại trừ các mối đe doạ hoà bình, cấm mọi hành vi xâm lược và phá hoại hoà bình khác, điều chỉnh hoặc giải quyết các vụ tranh chấp hoặc những tình thế có tính chất quốc tế có thể đưa đến sự phá hoại hoà bình, bằng biện pháp hoà bình theo đúng nguyên tắc của công lí và pháp luật quốc tế.\" (Trích: Điều 1, Hiến chương Liên hợp quốc, ngày 24-10-1945)\n\nNhận định sau đúng hay sai? Trong số các mục tiêu của Liên hợp quốc, duy trì hoà bình và an ninh quốc tế là mục tiêu được đặt lên hàng đầu.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":8,"question":"Đọc đoạn tư liệu sau: \"Duy trì hoà bình và an ninh quốc tế, và để đạt được mục đích đó, thi hành những biện pháp tập thể có hiệu quả để phòng ngừa và loại trừ các mối đe doạ hoà bình, cấm mọi hành vi xâm lược và phá hoại hoà bình khác, điều chỉnh hoặc giải quyết các vụ tranh chấp hoặc những tình thế có tính chất quốc tế có thể đưa đến sự phá hoại hoà bình, bằng biện pháp hoà bình theo đúng nguyên tắc của công lí và pháp luật quốc tế.\" (Trích: Điều 1, Hiến chương Liên hợp quốc, ngày 24-10-1945)\n\nNhận định sau đúng hay sai? Ngày nay, Liên hợp quốc vẫn tiếp tục thực hiện mục tiêu giải quyết các vụ tranh chấp, xung đột quốc tế bằng biện pháp hoà bình.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":9,"question":"Nội dung nào sau đây là mục tiêu hoạt động của Liên hợp quốc?","options":{"A":"Xây dựng một tổ chức Liên hợp quốc vững mạnh về quân sự và thịnh vượng về kinh tế.","B":"Hợp tác quốc tế trong việc giải quyết các vấn đề quốc tế về kinh tế, xã hội, văn hoá....","C":"Giải quyết thành công vấn đề an sinh, xã hội của từng quốc gia.","D":"Liên kết các quốc gia thành các trung tâm kinh tế - văn hoá."},"answer":"B"},{"id":10,"question":"Đọc đoạn tư liệu sau: “Tất cả các quốc gia thành viên Liên hợp quốc đều phải làm tròn những nghĩa vụ mà họ phải đảm nhận theo Hiến chương này để được bảo đảm hưởng toàn bộ các quyền và ưu đãi do tư cách thành viên mà có: Tất cả các thành viên của Liên hợp quốc giải quyết các tranh chấp quốc tế của họ bằng biện pháp hoà bình, sao cho không tổn hại đến hoà bình, an ninh quốc tế và công lí”. (Trích: Điều 2, Hiến chương Liên hợp quốc, ngày 24-10-1945)\n\nNhận định sau đúng hay sai? Đoạn tư liệu thể hiện mục tiêu hoạt động cơ bản của Liên hợp quốc là các quốc gia làm tròn nghĩa vụ đối với tổ chức này.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":11,"question":"Đọc đoạn tư liệu sau: “Tất cả các quốc gia thành viên Liên hợp quốc đều phải làm tròn những nghĩa vụ mà họ phải đảm nhận theo Hiến chương này để được bảo đảm hưởng toàn bộ các quyền và ưu đãi do tư cách thành viên mà có: Tất cả các thành viên của Liên hợp quốc giải quyết các tranh chấp quốc tế của họ bằng biện pháp hoà bình, sao cho không tổn hại đến hoà bình, an ninh quốc tế và công lí”. (Trích: Điều 2, Hiến chương Liên hợp quốc, ngày 24-10-1945)\n\nNhận định sau đúng hay sai? Đoạn tư liệu cho thấy một trong những nguyên tắc hoạt động của Liên hợp quốc là các quốc gia thành viên thực hiện những nghĩa vụ đảm nhận theo Hiến chương Liên hợp quốc.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":12,"question":"Đọc đoạn tư liệu sau: “Tất cả các quốc gia thành viên Liên hợp quốc đều phải làm tròn những nghĩa vụ mà họ phải đảm nhận theo Hiến chương này để được bảo đảm hưởng toàn bộ các quyền và ưu đãi do tư cách thành viên mà có: Tất cả các thành viên của Liên hợp quốc giải quyết các tranh chấp quốc tế của họ bằng biện pháp hoà bình, sao cho không tổn hại đến hoà bình, an ninh quốc tế và công lí”. (Trích: Điều 2, Hiến chương Liên hợp quốc, ngày 24-10-1945)\n\nNhận định sau đúng hay sai? Đoạn tư liệu là văn bản pháp lí giúp Liên hợp quốc ngăn chặn mọi xung đột giữa các thành viên từ khi tổ chức này thành lập.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":13,"question":"Đọc đoạn tư liệu sau: “Tất cả các quốc gia thành viên Liên hợp quốc đều phải làm tròn những nghĩa vụ mà họ phải đảm nhận theo Hiến chương này để được bảo đảm hưởng toàn bộ các quyền và ưu đãi do tư cách thành viên mà có: Tất cả các thành viên của Liên hợp quốc giải quyết các tranh chấp quốc tế của họ bằng biện pháp hoà bình, sao cho không tổn hại đến hoà bình, an ninh quốc tế và công lí”. (Trích: Điều 2, Hiến chương Liên hợp quốc, ngày 24-10-1945)\n\nNhận định sau đúng hay sai? Mặc dù Liên hợp quốc có những nguyên tắc hoạt động chặt chẽ, nhưng hiện nay giữa một số quốc gia thành viên vẫn diễn ra chiến tranh, xung đột.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":14,"question":"Nội dung nào sau đây không phải là biểu hiện của xu thế đa cực?","options":{"A":"Mỹ bị suy giảm sức mạnh tương đối trong tương quan so sánh với các cường quốc khác.","B":"Cách mạng công nghiệp lần thứ ba ngày càng đạt được nhiều thành tựu, đặc biệt là về kinh tế.","C":"Các trung tâm quyền lực ngày càng vươn lên, khẳng định sức mạnh về kinh tế, quân sự, chính trị đối với thế giới.","D":"Vai trò của các trung tâm, tổ chức kinh tế, tài chính quốc tế và khu vực ngày càng lớn."},"answer":"B"},{"id":15,"question":"Liên hợp quốc có vai trò thúc đẩy phát triển hợp tác quốc tế về","options":{"A":"liên minh quân sự.","B":"xây dựng bản sắc văn hoá chung.","C":"thương mại, dịch vụ, du lịch, tình báo.","D":"kinh tế, tài chính, thương mại, khoa học, kĩ thuật."},"answer":"D"},{"id":16,"question":"Nội dung nào sau đây là vai trò của Liên hợp quốc về bảo đảm quyền con người, phát triển văn hoá, xã hội?","options":{"A":"Giảm lãi suất cho vay ở hầu hết các nước phát triển.","B":"Tăng cường bình đẳng giới và vị thế, năng lực của phụ nữ.","C":"Cải thiện năng lực công nghệ thông tin.","D":"Hoàn thành phổ cập giáo dục đại học."},"answer":"B"},{"id":17,"question":"Trật tự thế giới hai cực I-an-ta được hình thành trong bối cảnh nào sau đây?","options":{"A":"Các nước Đồng minh muốn nhanh chóng đánh bại hoàn toàn chủ nghĩa phát xít.","B":"Chiến tranh thế giới thứ hai đã kết thúc ở châu Á và châu Phi.","C":"Sau Chiến tranh thế giới thứ hai, các nước Đồng minh tổ chức lại thế giới.","D":"Sau Chiến tranh thế giới thứ hai, các nước Đồng minh phân chia quyền lợi."},"answer":"C"},{"id":18,"question":"Tháng 2-1945, tại thành phố I-an-ta (Liên Xô), ba cường quốc Liên Xô, Mỹ, Anh đã","options":{"A":"thành lập Tổ chức Hiệp ước Bắc Đại Tây Dương (NATO).","B":"thành lập Hội Quốc liên để duy trì hoà bình và an ninh quốc tế.","C":"thoả thuận về việc phân chia phạm vi ảnh hưởng giữa các nước lớn.","D":"phân chia phạm vi ảnh hưởng của Mỹ và Liên Xô ở châu Phi."},"answer":"C"},{"id":19,"question":"Tại Hội nghị I-an-ta, theo thoả thuận của Liên Xô, Mỹ và các nước phương Tây, quân đội Liên Xô đóng quân ở khu vực nào sau đây?","options":{"A":"Miền Tây nước Đức, Đông Béc-lin và các nước Đông Âu.","B":"Miền Đông nước Đức, Đông Béc-lin và các nước Đông Âu.","C":"Tây Béc-lin, Đông Béc-lin và các nước Đông Âu.","D":"Vùng Tây Âu, Tây Béc-lin và các nước Đông Âu."},"answer":"B"},{"id":20,"question":"Sau Chiến tranh thế giới thứ hai, vùng Tây Âu thuộc phạm vi ảnh hưởng của","options":{"A":"Mỹ.","B":"Liên Xô.","C":"Pháp.","D":"các nước phương Tây."},"answer":"A"},{"id":21,"question":"Sau Chiến tranh thế giới thứ hai, một trật tự thế giới mới được thiết lập, thường được gọi là","options":{"A":"Trật tự thế giới đa cực.","B":"Trật tự thế giới đơn cực.","C":"Trật tự thế giới đơn cực I-an-ta.","D":"Trật tự thế giới hai cực I-an-ta."},"answer":"D"},{"id":22,"question":"Nội dung nào sau đây là mục tiêu của Mỹ khi phát động Chiến tranh lạnh (1947)?","options":{"A":"Đàn áp phong trào giải phóng dân tộc ở các nước thuộc địa.","B":"Chống lại các lực lượng khủng bố ở châu Âu.","C":"Chống lại Liên Xô và các nước Đông Âu.","D":"Thiết lập khối kinh tế ở các nước Đông Âu."},"answer":"C"},{"id":23,"question":"Nội dung nào sau đây là biểu hiện của Chiến tranh lạnh?","options":{"A":"Các cuộc chiến tranh cục bộ diễn ra ở nhiều nơi.","B":"Trung Quốc và Liên Xô chạy đua vũ trang.","C":"Trung Quốc và Mỹ trở thành hai cực lớn nhất.","D":"Mỹ phát triển trở thành một cực duy nhất."},"answer":"A"},{"id":24,"question":"Những năm 70 của thế kỉ XX, thế giới xuất hiện xu thế nào sau đây ảnh hưởng đến cục diện của Chiến tranh lạnh?","options":{"A":"Đa quốc gia.","B":"Hoà hoãn Đông - Tây.","C":"Công nghiệp hoá.","D":"Đơn cực."},"answer":"B"},{"id":25,"question":"Sự kiện nào sau đây chính thức chấm dứt sự tồn tại của Trật tự thế giới hai cực I-an-ta?","options":{"A":"Cuộc gặp giữa hai nhà lãnh đạo Liên Xô và Mỹ ở đảo Man-ta (1989).","B":"Liên Xô và Mỹ kí Hiệp ước hạn chế vũ khí chiến lược (SALT I).","C":"Sự tan rã của Liên Xô năm 1991.","D":"Liên Xô và Mỹ suy yếu."},"answer":"C"},{"id":26,"question":"Cho bảng dữ kiện về nguyên nhân sụp đổ Trật tự thế giới hai cực I-an-ta: (1) Chạy đua vũ trang khiến cả Liên Xô và Mỹ bị tốn kém, suy giảm thế mạnh kinh tế, buộc hai bên phải tự điều chỉnh, từng bước hạn chế căng thẳng. (2) Sự vươn lên của các nước trên thế giới nhằm thoát khỏi ảnh hưởng của hai cực. (3) Thắng lợi của phong trào giải phóng dân tộc và sự ra đời của hàng loạt các quốc gia độc lập. (4) Sự thay đổi trong cán cân kinh tế thế giới, đặc biệt là sự nổi lên của Nhật Bản và các nước Tây Âu. (5) Xu thế hoà hoãn, toàn cầu hoá và ảnh hưởng của cuộc Cách mạng công nghiệp lần thứ ba. (6) Sự khủng hoảng, suy yếu rồi tan rã của Liên Xô - quốc gia đứng đầu hệ thống xã hội chủ nghĩa.\n\nNhận định sau đúng hay sai? Trật tự hai cực I-an-ta sụp đổ là do sự phát triển mạnh mẽ của nền kinh tế Mỹ và Tây Âu từ sau Chiến tranh thế giới thứ hai.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":27,"question":"Cho bảng dữ kiện về nguyên nhân sụp đổ Trật tự thế giới hai cực I-an-ta: (1) Chạy đua vũ trang khiến cả Liên Xô và Mỹ bị tốn kém, suy giảm thế mạnh kinh tế, buộc hai bên phải tự điều chỉnh, từng bước hạn chế căng thẳng. (2) Sự vươn lên của các nước trên thế giới nhằm thoát khỏi ảnh hưởng của hai cực. (3) Thắng lợi của phong trào giải phóng dân tộc và sự ra đời của hàng loạt các quốc gia độc lập. (4) Sự thay đổi trong cán cân kinh tế thế giới, đặc biệt là sự nổi lên của Nhật Bản và các nước Tây Âu. (5) Xu thế hoà hoãn, toàn cầu hoá và ảnh hưởng của cuộc Cách mạng công nghiệp lần thứ ba. (6) Sự khủng hoảng, suy yếu rồi tan rã của Liên Xô - quốc gia đứng đầu hệ thống xã hội chủ nghĩa.\n\nNhận định sau đúng hay sai? Xu thế toàn cầu hoá khiến cho tình trạng chạy đua vũ trang của Mỹ và Liên Xô không còn phù hợp.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":28,"question":"Cho bảng dữ kiện về nguyên nhân sụp đổ Trật tự thế giới hai cực I-an-ta: (1) Chạy đua vũ trang khiến cả Liên Xô và Mỹ bị tốn kém, suy giảm thế mạnh kinh tế, buộc hai bên phải tự điều chỉnh, từng bước hạn chế căng thẳng. (2) Sự vươn lên của các nước trên thế giới nhằm thoát khỏi ảnh hưởng của hai cực. (3) Thắng lợi của phong trào giải phóng dân tộc và sự ra đời của hàng loạt các quốc gia độc lập. (4) Sự thay đổi trong cán cân kinh tế thế giới, đặc biệt là sự nổi lên của Nhật Bản và các nước Tây Âu. (5) Xu thế hoà hoãn, toàn cầu hoá và ảnh hưởng của cuộc Cách mạng công nghiệp lần thứ ba. (6) Sự khủng hoảng, suy yếu rồi tan rã của Liên Xô - quốc gia đứng đầu hệ thống xã hội chủ nghĩa.\n\nNhận định sau đúng hay sai? Trật tự thế giới hai cực I-an-ta sụp đổ gắn liền với sự khủng hoảng và suy yếu của Liên Xô.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":29,"question":"Cho bảng dữ kiện về nguyên nhân sụp đổ Trật tự thế giới hai cực I-an-ta: (1) Chạy đua vũ trang khiến cả Liên Xô và Mỹ bị tốn kém, suy giảm thế mạnh kinh tế, buộc hai bên phải tự điều chỉnh, từng bước hạn chế căng thẳng. (2) Sự vươn lên của các nước trên thế giới nhằm thoát khỏi ảnh hưởng của hai cực. (3) Thắng lợi của phong trào giải phóng dân tộc và sự ra đời của hàng loạt các quốc gia độc lập. (4) Sự thay đổi trong cán cân kinh tế thế giới, đặc biệt là sự nổi lên của Nhật Bản và các nước Tây Âu. (5) Xu thế hoà hoãn, toàn cầu hoá và ảnh hưởng của cuộc Cách mạng công nghiệp lần thứ ba. (6) Sự khủng hoảng, suy yếu rồi tan rã của Liên Xô - quốc gia đứng đầu hệ thống xã hội chủ nghĩa.\n\nNhận định sau đúng hay sai? Sự vươn lên của các nước đang phát triển khiến cho Mỹ suy yếu, không còn đủ sức chạy đua kinh tế.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":30,"question":"Nội dung nào sau đây là tác động của sự sụp đổ Trật tự thế giới hai cực I-an-ta?","options":{"A":"Một trật tự thế giới mới dần hình thành theo xu thế đơn cực.","B":"Mở ra chiều hướng và điều kiện thuận lợi để giải quyết hoà bình các cuộc tranh chấp, xung đột.","C":"Sự phát triển vượt trội của các nước xã hội chủ nghĩa, đặc biệt là về kinh tế, khoa học, quân sự.","D":"Các vấn đề về dân tộc, bản sắc cộng đồng, tôn giáo trên thế giới đã được giải quyết một cách căn bản."},"answer":"B"},{"id":31,"question":"Đọc đoạn tư liệu sau: \"Bài học của thời kì Chiến tranh lạnh đã chứng tỏ phương thức quan hệ quốc tế lấy đối đầu chính trị – quân sự là chủ yếu không còn phù hợp, phải chịu nhiều tổn thất hoặc thất bại như hai nước Xô – Mỹ, một bị thương, một bị mất. Trong khi đó, phương thức lấy hợp tác và cạnh tranh về kinh tế - chính trị là chính lại thu được nhiều tiến bộ, kết quả như các nước Đức, Nhật và NICs. Sự hưng thịnh hay suy vong của một quốc gia quyết định bởi sức mạnh tổng hợp của quốc gia đó, mà chủ yếu là thực lực kinh tế và khoa học – kĩ thuật\". (Vũ Dương Ninh (Chủ biên), Một số chuyên đề lịch sử thế giới, NXB Đại học Quốc gia Hà Nội, 2001, tr.401)\n\nNhận định sau đúng hay sai? Hợp tác về kinh tế - chính trị làm suy yếu tiềm lực phát triển của từng nước.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":32,"question":"Đọc đoạn tư liệu sau: \"Bài học của thời kì Chiến tranh lạnh đã chứng tỏ phương thức quan hệ quốc tế lấy đối đầu chính trị – quân sự là chủ yếu không còn phù hợp, phải chịu nhiều tổn thất hoặc thất bại như hai nước Xô – Mỹ, một bị thương, một bị mất. Trong khi đó, phương thức lấy hợp tác và cạnh tranh về kinh tế - chính trị là chính lại thu được nhiều tiến bộ, kết quả như các nước Đức, Nhật và NICs. Sự hưng thịnh hay suy vong của một quốc gia quyết định bởi sức mạnh tổng hợp của quốc gia đó, mà chủ yếu là thực lực kinh tế và khoa học – kĩ thuật\". (Vũ Dương Ninh (Chủ biên), Một số chuyên đề lịch sử thế giới, NXB Đại học Quốc gia Hà Nội, 2001, tr.401)\n\nNhận định sau đúng hay sai? Tình trạng đối đầu về chính trị - quân sự của Mỹ và Liên Xô trong Chiến tranh lạnh khiến cho hai nước chịu nhiều tổn thất.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":33,"question":"Đọc đoạn tư liệu sau: \"Bài học của thời kì Chiến tranh lạnh đã chứng tỏ phương thức quan hệ quốc tế lấy đối đầu chính trị – quân sự là chủ yếu không còn phù hợp, phải chịu nhiều tổn thất hoặc thất bại như hai nước Xô – Mỹ, một bị thương, một bị mất. Trong khi đó, phương thức lấy hợp tác và cạnh tranh về kinh tế - chính trị là chính lại thu được nhiều tiến bộ, kết quả như các nước Đức, Nhật và NICs. Sự hưng thịnh hay suy vong của một quốc gia quyết định bởi sức mạnh tổng hợp của quốc gia đó, mà chủ yếu là thực lực kinh tế và khoa học – kĩ thuật\". (Vũ Dương Ninh (Chủ biên), Một số chuyên đề lịch sử thế giới, NXB Đại học Quốc gia Hà Nội, 2001, tr.401)\n\nNhận định sau đúng hay sai? Thực lực kinh tế và khoa học – kĩ thuật có vai trò quan trọng đối với sự phát triển của một quốc gia.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":34,"question":"Đọc đoạn tư liệu sau: \"Bài học của thời kì Chiến tranh lạnh đã chứng tỏ phương thức quan hệ quốc tế lấy đối đầu chính trị – quân sự là chủ yếu không còn phù hợp, phải chịu nhiều tổn thất hoặc thất bại như hai nước Xô – Mỹ, một bị thương, một bị mất. Trong khi đó, phương thức lấy hợp tác và cạnh tranh về kinh tế - chính trị là chính lại thu được nhiều tiến bộ, kết quả như các nước Đức, Nhật và NICs. Sự hưng thịnh hay suy vong của một quốc gia quyết định bởi sức mạnh tổng hợp của quốc gia đó, mà chủ yếu là thực lực kinh tế và khoa học – kĩ thuật\". (Vũ Dương Ninh (Chủ biên), Một số chuyên đề lịch sử thế giới, NXB Đại học Quốc gia Hà Nội, 2001, tr.401)\n\nNhận định sau đúng hay sai? Đoạn tư liệu thể hiện xu thế phát triển chính của thế giới sau Chiến tranh lạnh.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":35,"question":"Khái niệm \"đa cực\" được hiểu là","options":{"A":"trạng thái địa - văn hoá toàn cầu với nhiều trung tâm quyền lực chi phối.","B":"một trật tự mới với vai trò vượt trội của Mỹ, chi phối các nước khác.","C":"một trật tự thế giới mà các nước vừa và nhỏ có vai trò quyết định.","D":"trạng thái địa - chính trị toàn cầu với nhiều trung tâm quyền lực chi phối."},"answer":"D"},{"id":36,"question":"Tại Hội nghị Tê-hê-ran, ba nước nào khẳng định quyết tâm thành lập Liên hợp quốc?","options":{"A":"Liên Xô, Mỹ, Trung Quốc.","B":"Nga, Pháp, Việt Nam.","C":"Liên Xô, Anh, Nhật Bản.","D":"Liên Xô, Mỹ, Anh."},"answer":"D"},{"id":37,"question":"Lễ kí Hiến chương Liên hợp quốc được tổ chức tại","options":{"A":"Xan Phran-xi-xcô (Mỹ).","B":"I-an-ta (Liên Xô).","C":"Tê-hê-ran (I-ran).","D":"Niu Oóc (Mỹ)."},"answer":"A"},{"id":38,"question":"Mục tiêu quan trọng nhất và là cơ sở để thực hiện các mục tiêu khác của Liên hợp quốc là","options":{"A":"thúc đẩy quan hệ hữu nghị giữa các dân tộc.","B":"thúc đẩy hợp tác quốc tế.","C":"trung tâm điều hòa các nỗ lực quốc tế.","D":"duy trì hòa bình và an ninh quốc tế."},"answer":"D"},{"id":39,"question":"Cơ quan nào của Liên hợp quốc đóng vai trò là cơ quan chính trị quan trọng nhất, chịu trách nhiệm duy trì hòa bình và an ninh thế giới?","options":{"A":"Đại hội đồng.","B":"Hội đồng Bảo an.","C":"Tòa án Quốc tế.","D":"Hội đồng Quản thác."},"answer":"B"},{"id":40,"question":"Hội nghị nào ra quyết định cho sự ra đời của tổ chức Liên hợp quốc?","options":{"A":"Hội nghị I-an-ta.","B":"Hội nghị Xan Phran-xi-xcô.","C":"Hội nghị Pốt-xđam.","D":"Hội nghị Pa-ri."},"answer":"A"},{"id":41,"question":"Tổ chức nào dưới đây là tiền thân của tổ chức Liên hợp quốc ngày nay?","options":{"A":"Liên minh tiến bộ quốc tế.","B":"Đệ tam quốc tế.","C":"Hội Quốc liên.","D":"Khối Đồng minh chống phát xít."},"answer":"C"},{"id":42,"question":"Đâu không phải là nguyên tắc cơ bản của Liên hợp quốc?","options":{"A":"Bình đẳng về chủ quyền quốc gia.","B":"Tôn trọng toàn vẹn lãnh thổ và độc lập chính trị quốc gia.","C":"Đe dọa bằng vũ lực hoặc sử dụng vũ lực trong quan hệ quốc tế.","D":"Giải quyết các tranh chấp quốc tế bằng biện pháp hòa bình."},"answer":"C"},{"id":43,"question":"Đâu không phải là vai trò của Liên hợp quốc?","options":{"A":"Duy trì hòa bình, an ninh quốc tế.","B":"Thúc đẩy hợp tác quốc tế về chính trị.","C":"Thúc đẩy phát triển kinh tế, tài chính, thương mại quốc tế.","D":"Đảm bảo quyền con người, phát triển văn hóa, xã hội."},"answer":"B"},{"id":44,"question":"Hội nghị I-an-ta diễn ra trong hoàn cảnh","options":{"A":"Chiến tranh thế giới thứ hai bùng nổ.","B":"Chiến tranh thế giới thứ hai sắp kết thúc.","C":"Chiến tranh thế giới thứ hai kết thúc.","D":"Chiến tranh thế giới thứ hai chưa diễn ra."},"answer":"B"},{"id":45,"question":"Những nước nào sau đây là thành phần tham gia Hội nghị I-an-ta (2/1945)?","options":{"A":"Anh – Pháp – Mĩ.","B":"Liên Xô – Mĩ – Anh.","C":"Liên Xô – Mĩ – Trung Quốc.","D":"Nhật – Anh – Pháp."},"answer":"B"},{"id":46,"question":"Đâu không phải là vấn đề cấp bách đặt ra trong Hội nghị I-an-ta (2-1945)?","options":{"A":"Nhanh chóng đánh bại hoàn toàn các nước phát xít.","B":"Phân chia thành quả chiến tranh giữa các nước thắng trận.","C":"Nhanh chóng khắc phục hậu quả chiến tranh.","D":"Tổ chức lại trật tự thế giới sau chiến tranh."},"answer":"C"},{"id":47,"question":"Trật tự thế giới mới hình thành sau Chiến tranh thế giới thứ hai có đặc điểm là","options":{"A":"hoàn toàn do CNTB thao túng và áp đặt quyền thống trị.","B":"có sự đối đầu giữa hai phe XHCN và TBCN.","C":"thiết lập trên cơ sở các nước thắng trận áp đặt thống trị với các nước châu Á.","D":"thiết lập trên cơ sở các nước thắng trận hợp tác để cùng nhau phát triển."},"answer":"B"},{"id":48,"question":"Tháng 12-1989, hai nhà lãnh đạo Xô – Mĩ đã cùng tuyên bố vấn đề gì?","options":{"A":"Vấn đề chấm dứt Chiến tranh lạnh.","B":"Vấn đề hạn chế vũ khí hạt nhân hủy diệt.","C":"Vấn đề chấm dứt chạy đua vũ trang.","D":"Vấn đề gìn giữ hòa bình, an ninh cho nhân loại."},"answer":"A"},{"id":49,"question":"Năm 1989, Mĩ và Liên Xô tuyên bố chấm dứt “Chiến tranh lạnh” vì nguyên nhân nào sau đây?","options":{"A":"Các nước Tây Âu, Nhật Bản đã vượt xa Liên Xô và Mĩ về khoa học - kĩ thuật.","B":"Trong xu thế toàn cầu hóa, sức mạnh quân sự phải nhường chỗ cho sức mạnh kinh tế.","C":"Nền kinh tế Mĩ và Liên Xô suy giảm, Mĩ bị Nhật Bản và Tây Âu cạnh tranh.","D":"Nhân dân trên thế giới phản đối cuộc chạy đua vũ trang của Mĩ và Liên Xô."},"answer":"C"},{"id":50,"question":"Ý nào sau đây không phải là nguyên tắc hoạt động của Liên hợp quốc?","options":{"A":"Tôn trọng toàn vẹn lãnh thổ và độc lập chính trị của tất cả các nước.","B":"Duy trì hòa bình và an ninh thế giới.","C":"Giải quyết các tranh chấp quốc tế bằng biện pháp hòa bình.","D":"Bình đẳng chủ quyền giữa các quốc gia và quyền tự quyết của các dân tộc."},"answer":"B"},{"id":51,"question":"Đâu là một trong những biểu hiện của Trật tự thế giới hai cực I-an-ta?","options":{"A":"Mỹ bình thường hóa quan hệ với Việt Nam.","B":"Sự vươn lên của Nga và Trung Quốc.","C":"Triều Tiên bị chia cắt làm hai quốc gia.","D":"Đông và Tây Đức chính thức hợp nhất."},"answer":"C"},{"id":52,"question":"Trật tự thế giới hai cực I-an-ta là sự đối đầu sâu sắc về hệ tư tưởng giữa","options":{"A":"Mỹ, Anh.","B":"Mỹ, Liên Xô.","C":"Mỹ, Pháp.","D":"Liên Xô, Anh."},"answer":"B"},{"id":53,"question":"Hậu quả nặng nề nhất mang lại cho thế giới trong suốt thời gian Trật tự thế giới hai cực I-an-ta là","options":{"A":"các nước ráo riết tăng cường chạy đua vũ trang.","B":"nhiều căn cứ quân sự được thiết lập trên toàn cầu.","C":"kinh tế các nước bị thiệt hại nặng nề.","D":"thế giới luôn trong tình trạng căng thẳng, đối đầu."},"answer":"D"},{"id":54,"question":"Ngày 24-10-1945, Liên hợp quốc chính thức được thành lập với bao nhiêu nước thành viên tham gia?","options":{"A":"51 nước.","B":"26 nước.","C":"40 nước.","D":"50 nước."},"answer":"A"},{"id":55,"question":"Mục tiêu và nguyên tắc hoạt động của Liên hợp quốc được quy định bởi văn kiện nào?","options":{"A":"Hiến chương.","B":"Hiến pháp.","C":"Tuyên ngôn.","D":"Hiệp định."},"answer":"A"},{"id":56,"question":"Liên hợp quốc quyết định lấy ngày 24-10 hằng năm làm Ngày Liên hợp quốc vì đó là ngày","options":{"A":"kết thúc Chiến tranh lạnh.","B":"bế mạc Hội nghị I-an-ta.","C":"Hiến chương Liên hợp quốc có hiệu lực.","D":"khai mạc lễ thành lập Liên hợp quốc."},"answer":"C"},{"id":57,"question":"Đâu là một trong những nội dung của mục tiêu, hành động mang tính toàn cầu đến năm 2030 của Liên hợp quốc?","options":{"A":"Chống nạn thất nghiệp.","B":"Quyền tự do chính trị.","C":"Chống bạo lực gia đình.","D":"Chất lượng giáo dục."},"answer":"D"},{"id":58,"question":"Đọc đoạn tư liệu sau: “Tất cả các quốc gia thành viên Liên hợp quốc đều phải làm tròn những nghĩa vụ mà họ phải đảm nhận theo Hiến chương này để được đảm bảo hưởng toàn bộ các quyền và ưu đãi do tư cách thành viên mà có”.\n\nNhận định sau đúng hay sai? Các nguyên tắc hoạt động của Liên hợp quốc bao gồm: giải quyết các tranh chấp quốc tế bằng biện pháp hòa bình.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":59,"question":"Đọc đoạn tư liệu sau: “Tất cả các quốc gia thành viên Liên hợp quốc đều phải làm tròn những nghĩa vụ mà họ phải đảm nhận theo Hiến chương này để được đảm bảo hưởng toàn bộ các quyền và ưu đãi do tư cách thành viên mà có”.\n\nNhận định sau đúng hay sai? Các nguyên tắc hoạt động của Liên hợp quốc bao gồm: từ bỏ đe dọa bằng hoặc sử dụng vũ lực trong quan hệ quốc tế.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":60,"question":"Đọc đoạn tư liệu sau: “Tất cả các quốc gia thành viên Liên hợp quốc đều phải làm tròn những nghĩa vụ mà họ phải đảm nhận theo Hiến chương này để được đảm bảo hưởng toàn bộ các quyền và ưu đãi do tư cách thành viên mà có”.\n\nNhận định sau đúng hay sai? Các nguyên tắc hoạt động của Liên hợp quốc bao gồm: không can thiệp vào công việc nội bộ của bất kì nước nào.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":61,"question":"Đọc đoạn tư liệu sau: “Tất cả các quốc gia thành viên Liên hợp quốc đều phải làm tròn những nghĩa vụ mà họ phải đảm nhận theo Hiến chương này để được đảm bảo hưởng toàn bộ các quyền và ưu đãi do tư cách thành viên mà có”.\n\nNhận định sau đúng hay sai? Các nguyên tắc hoạt động của Liên hợp quốc bao gồm: tôn trọng các nghĩa vụ quốc tế và luật pháp quốc tế.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":62,"question":"Đọc đoạn tư liệu sau: Tháng 12/1989, trong cuộc gặp không chính thức tại đảo Man-ta (Địa Trung Hải), Tổng Bí thư Đảng Cộng sản Liên Xô M. Goóc-ba-chốp và Tổng thống Mĩ G. Bút-sơ đã chính thức cùng tuyên bố chấm dứt Chiến tranh lạnh. Chiến tranh lạnh chấm dứt đã mở ra chiều hướng và những điều kiện giải quyết hòa bình các vụ tranh chấp, xung đột đang diễn ra ở nhiều khu vực trên thế giới. Tuy vậy, tình trạng Chiến tranh lạnh chỉ thực sự kết thúc sau khi Liên bang Xô viết tan rã, trật tự hai cực I-an-ta không còn nữa.\n\nNhận định sau đúng hay sai? Trật tự thế giới hai cực I-an-ta gắn liền với những diễn biến của cuộc Chiến tranh lạnh giữa hai cực Mỹ - Xô.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":63,"question":"Đọc đoạn tư liệu sau: Tháng 12/1989, trong cuộc gặp không chính thức tại đảo Man-ta (Địa Trung Hải), Tổng Bí thư Đảng Cộng sản Liên Xô M. Goóc-ba-chốp và Tổng thống Mĩ G. Bút-sơ đã chính thức cùng tuyên bố chấm dứt Chiến tranh lạnh. Chiến tranh lạnh chấm dứt đã mở ra chiều hướng và những điều kiện giải quyết hòa bình các vụ tranh chấp, xung đột đang diễn ra ở nhiều khu vực trên thế giới. Tuy vậy, tình trạng Chiến tranh lạnh chỉ thực sự kết thúc sau khi Liên bang Xô viết tan rã, trật tự hai cực I-an-ta không còn nữa.\n\nNhận định sau đúng hay sai? Sau khi Chiến tranh lạnh chấm dứt, thế giới phát triển theo xu thế đối thoại, hợp tác trong quan hệ quốc tế.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":64,"question":"Đọc đoạn tư liệu sau: Tháng 12/1989, trong cuộc gặp không chính thức tại đảo Man-ta (Địa Trung Hải), Tổng Bí thư Đảng Cộng sản Liên Xô M. Goóc-ba-chốp và Tổng thống Mĩ G. Bút-sơ đã chính thức cùng tuyên bố chấm dứt Chiến tranh lạnh. Chiến tranh lạnh chấm dứt đã mở ra chiều hướng và những điều kiện giải quyết hòa bình các vụ tranh chấp, xung đột đang diễn ra ở nhiều khu vực trên thế giới. Tuy vậy, tình trạng Chiến tranh lạnh chỉ thực sự kết thúc sau khi Liên bang Xô viết tan rã, trật tự hai cực I-an-ta không còn nữa.\n\nNhận định sau đúng hay sai? Một trong những nguyên nhân dẫn đến sụp đổ của Trật tự thế giới hai cực I-an-ta là do Liên Xô lâm vào tình trạng khủng hoảng.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":65,"question":"Đọc đoạn tư liệu sau: Tháng 12/1989, trong cuộc gặp không chính thức tại đảo Man-ta (Địa Trung Hải), Tổng Bí thư Đảng Cộng sản Liên Xô M. Goóc-ba-chốp và Tổng thống Mĩ G. Bút-sơ đã chính thức cùng tuyên bố chấm dứt Chiến tranh lạnh. Chiến tranh lạnh chấm dứt đã mở ra chiều hướng và những điều kiện giải quyết hòa bình các vụ tranh chấp, xung đột đang diễn ra ở nhiều khu vực trên thế giới. Tuy vậy, tình trạng Chiến tranh lạnh chỉ thực sự kết thúc sau khi Liên bang Xô viết tan rã, trật tự hai cực I-an-ta không còn nữa.\n\nNhận định sau đúng hay sai? Khi Trật tự thế giới hai cực I-an-ta chấm dứt, Việt Nam mới bắt đầu bước vào công cuộc đổi mới đất nước.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":66,"question":"Đọc đoạn tư liệu sau: Đa cực là một thuật ngữ trong quan hệ quốc tế dùng để chỉ một trật tự thế giới có sự tham gia của các quốc gia, các trung tâm khác nhau, trong đó không một quốc gia nào có quyền lực áp đảo đối với các quốc gia khác, cũng như chi phối sự phát triển của thế giới. Sự hình thành của trật tự thế giới đa cực là một tiến trình lịch sử khách quan với sự nổi lên của các cường quốc, sự gia tăng vai trò của các trung tâm, tổ chức quốc tế, phản ánh tương quan so sánh lực lượng mới trong quan hệ quốc tế sau Chiến tranh lạnh.\n\nNhận định sau đúng hay sai? “Đa cực” là một thuật ngữ dùng để chỉ tên của một trật tự thế giới mới đang được hình thành sau khi Chiến tranh lạnh kết thúc.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":67,"question":"Đọc đoạn tư liệu sau: Đa cực là một thuật ngữ trong quan hệ quốc tế dùng để chỉ một trật tự thế giới có sự tham gia của các quốc gia, các trung tâm khác nhau, trong đó không một quốc gia nào có quyền lực áp đảo đối với các quốc gia khác, cũng như chi phối sự phát triển của thế giới. Sự hình thành của trật tự thế giới đa cực là một tiến trình lịch sử khách quan với sự nổi lên của các cường quốc, sự gia tăng vai trò của các trung tâm, tổ chức quốc tế, phản ánh tương quan so sánh lực lượng mới trong quan hệ quốc tế sau Chiến tranh lạnh.\n\nNhận định sau đúng hay sai? Sự hình thành trật tự thế giới đa cực mang tính khách quan vì đó là kết quả của cuộc chạy đua về sức mạnh tổng hợp của các cường quốc.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":68,"question":"Đọc đoạn tư liệu sau: Đa cực là một thuật ngữ trong quan hệ quốc tế dùng để chỉ một trật tự thế giới có sự tham gia của các quốc gia, các trung tâm khác nhau, trong đó không một quốc gia nào có quyền lực áp đảo đối với các quốc gia khác, cũng như chi phối sự phát triển của thế giới. Sự hình thành của trật tự thế giới đa cực là một tiến trình lịch sử khách quan với sự nổi lên của các cường quốc, sự gia tăng vai trò của các trung tâm, tổ chức quốc tế, phản ánh tương quan so sánh lực lượng mới trong quan hệ quốc tế sau Chiến tranh lạnh.\n\nNhận định sau đúng hay sai? Trật tự thế giới đa cực có sự tham gia của các quốc gia, các trung tâm khác nhau, trong đó các quốc gia và trung tâm có quyền lực hoàn toàn ngang bằng nhau.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":69,"question":"Đọc đoạn tư liệu sau: Đa cực là một thuật ngữ trong quan hệ quốc tế dùng để chỉ một trật tự thế giới có sự tham gia của các quốc gia, các trung tâm khác nhau, trong đó không một quốc gia nào có quyền lực áp đảo đối với các quốc gia khác, cũng như chi phối sự phát triển của thế giới. Sự hình thành của trật tự thế giới đa cực là một tiến trình lịch sử khách quan với sự nổi lên của các cường quốc, sự gia tăng vai trò của các trung tâm, tổ chức quốc tế, phản ánh tương quan so sánh lực lượng mới trong quan hệ quốc tế sau Chiến tranh lạnh.\n\nNhận định sau đúng hay sai? Trật tự hai cực I-an-ta và trật tự thế giới đa cực đều phản ánh tương quan so sánh lực lượng mới giữa các cường quốc trong quan hệ quốc tế.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":70,"question":"Đọc đoạn tư liệu dưới đây: [Năm 1960], “Đại hội đồng Liên hợp quốc đã thông qua bản Tuyên ngôn về thủ tiêu hoàn toàn chủ nghĩa thực dân, trao trả độc lập cho các quốc gia và dân tộc thuộc địa. Đó là một sự kiện chính trị quan trọng. Như thế, tuyên ngôn đã khẳng định các nước thực dân đã vi phạm nguyên tắc quan trọng nhất của luật pháp quốc tế; khẳng định rõ ràng cơ sở pháp lí quốc tế của cuộc đấu tranh giành độc lập của các dân tộc bị áp bức”.\n\nNhận định sau đúng hay sai? Tuyên ngôn về thủ tiêu hoàn toàn chủ nghĩa thực dân của Liên hợp quốc đã góp phần nói lên nguyện vọng của các dân tộc bị áp bức.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":71,"question":"Đọc đoạn tư liệu dưới đây: [Năm 1960], “Đại hội đồng Liên hợp quốc đã thông qua bản Tuyên ngôn về thủ tiêu hoàn toàn chủ nghĩa thực dân, trao trả độc lập cho các quốc gia và dân tộc thuộc địa. Đó là một sự kiện chính trị quan trọng. Như thế, tuyên ngôn đã khẳng định các nước thực dân đã vi phạm nguyên tắc quan trọng nhất của luật pháp quốc tế; khẳng định rõ ràng cơ sở pháp lí quốc tế của cuộc đấu tranh giành độc lập của các dân tộc bị áp bức”.\n\nNhận định sau đúng hay sai? Tuyên ngôn về thủ tiêu hoàn toàn chủ nghĩa thực dân (năm 1960) của Liên hợp quốc đã tạo ra cơ sở pháp lí cho các cuộc đấu tranh giành độc lập của nhân dân các nước Á, Phi, Mỹ La-tinh.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":72,"question":"Đọc đoạn tư liệu dưới đây: [Năm 1960], “Đại hội đồng Liên hợp quốc đã thông qua bản Tuyên ngôn về thủ tiêu hoàn toàn chủ nghĩa thực dân, trao trả độc lập cho các quốc gia và dân tộc thuộc địa. Đó là một sự kiện chính trị quan trọng. Như thế, tuyên ngôn đã khẳng định các nước thực dân đã vi phạm nguyên tắc quan trọng nhất của luật pháp quốc tế; khẳng định rõ ràng cơ sở pháp lí quốc tế của cuộc đấu tranh giành độc lập của các dân tộc bị áp bức”.\n\nNhận định sau đúng hay sai? Tuyên ngôn về thủ tiêu hoàn toàn chủ nghĩa thực dân (năm 1960) đã thông qua các nguyên tắc hoạt động cơ bản của tổ chức Liên hợp quốc.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":73,"question":"Đọc đoạn tư liệu dưới đây: [Năm 1960], “Đại hội đồng Liên hợp quốc đã thông qua bản Tuyên ngôn về thủ tiêu hoàn toàn chủ nghĩa thực dân, trao trả độc lập cho các quốc gia và dân tộc thuộc địa. Đó là một sự kiện chính trị quan trọng. Như thế, tuyên ngôn đã khẳng định các nước thực dân đã vi phạm nguyên tắc quan trọng nhất của luật pháp quốc tế; khẳng định rõ ràng cơ sở pháp lí quốc tế của cuộc đấu tranh giành độc lập của các dân tộc bị áp bức”.\n\nNhận định sau đúng hay sai? Đoạn tư liệu đã thể hiện vai trò quan trọng nhất của tổ chức Liên hợp quốc là duy trì hòa bình, an ninh thế giới.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":74,"question":"Bối cảnh quốc tế nào sau đây dẫn đến quá trình hình thành của Hiệp hội các quốc gia Đông Nam Á (ASEAN)?","options":{"A":"Các nước Đông Nam Á giành được độc lập, thống nhất.","B":"Sự ra đời của tổ chức NATO và các liên minh quân sự.","C":"Sự ra đời của Tổ chức Hiệp ước Vác-sa-va.","D":"Sự phát triển của xu thế khu vực hoá trên thế giới."},"answer":"D"},{"id":75,"question":"Tổ chức khu vực nào sau đây được thành lập ở Đông Nam Á năm 1963?","options":{"A":"MAPHILINDO.","B":"NAFTA.","C":"APEC.","D":"EU."},"answer":"A"},{"id":76,"question":"Hiệp hội các quốc gia Đông Nam Á được thành lập năm 1967 tại","options":{"A":"Ma-ni-la (Phi-líp-pin).","B":"Cua-la Lăm-pơ (Ma-lai-xi-a).","C":"Ba-li (In-đô-nê-xi-a).","D":"Băng Cốc (Thái Lan)."},"answer":"D"},{"id":77,"question":"Các nước sáng lập ASEAN là","options":{"A":"Việt Nam, Thái Lan, Phi-líp-pin, Xin-ga-po, Ma-lai-xi-a.","B":"In-đô-nê-xi-a, Ma-lai-xi-a, Phi-líp-pin, Xin-ga-po, Thái Lan.","C":"Thái Lan, Phi-líp-pin, Xin-ga-po, Ma-lai-xi-a, Mi-an-ma.","D":"Lào, Thái Lan, Phi-líp-pin, Xin-ga-po, Ma-lai-xi-a."},"answer":"B"},{"id":78,"question":"Một trong những mục đích thành lập của ASEAN là","options":{"A":"thúc đẩy tăng trưởng kinh tế, tiến bộ xã hội trong khu vực.","B":"tăng cường hợp tác quốc phòng, an ninh và hình thành liên minh phòng thủ.","C":"thành lập một tổ chức chính trị, quân sự chung trong khu vực Đông Nam Á.","D":"giải quyết tranh chấp trong khu vực bằng biện pháp quân sự hoà bình."},"answer":"A"},{"id":79,"question":"Đọc đoạn tư liệu sau: “Nhận thức được sự tồn tại của các mối quan tâm lẫn nhau và các vấn đề chung giữa các nước Đông Nam Á và tin tưởng vào sự cần thiết phải tăng cường hơn nữa các mối quan hệ đoàn kết sẵn có trong khu vực; mong muốn xây dựng một nền tảng vững chắc cho hành động chung nhằm thúc đẩy hợp tác khu vực ở Đông Nam Á, các nước Đông Nam Á có trách nhiệm chính trong việc tăng cường ổn định kinh tế và xã hội của khu vực và bảo đảm sự phát triển đất nước hoà bình và tiến bộ, quyết tâm bảo đảm sự ổn định và an ninh không có sự can thiệp từ bên ngoài dưới bất kì hình thức hoặc biểu hiện nào”.\n\nNhận định sau đúng hay sai? Tuyên bố Băng Cốc là văn kiện được đưa ra sau khi ASEAN đã được thành lập và đi vào hoạt động.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":80,"question":"Đọc đoạn tư liệu sau: “Nhận thức được sự tồn tại của các mối quan tâm lẫn nhau và các vấn đề chung giữa các nước Đông Nam Á và tin tưởng vào sự cần thiết phải tăng cường hơn nữa các mối quan hệ đoàn kết sẵn có trong khu vực; mong muốn xây dựng một nền tảng vững chắc cho hành động chung nhằm thúc đẩy hợp tác khu vực ở Đông Nam Á, các nước Đông Nam Á có trách nhiệm chính trong việc tăng cường ổn định kinh tế và xã hội của khu vực và bảo đảm sự phát triển đất nước hoà bình và tiến bộ, quyết tâm bảo đảm sự ổn định và an ninh không có sự can thiệp từ bên ngoài dưới bất kì hình thức hoặc biểu hiện nào”.\n\nNhận định sau đúng hay sai? Tuyên bố Băng Cốc cho thấy một trong những mục đích thành lập của ASEAN là thúc đẩy hợp tác.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":81,"question":"Đọc đoạn tư liệu sau: “Nhận thức được sự tồn tại của các mối quan tâm lẫn nhau và các vấn đề chung giữa các nước Đông Nam Á và tin tưởng vào sự cần thiết phải tăng cường hơn nữa các mối quan hệ đoàn kết sẵn có trong khu vực; mong muốn xây dựng một nền tảng vững chắc cho hành động chung nhằm thúc đẩy hợp tác khu vực ở Đông Nam Á, các nước Đông Nam Á có trách nhiệm chính trong việc tăng cường ổn định kinh tế và xã hội của khu vực và bảo đảm sự phát triển đất nước hoà bình và tiến bộ, quyết tâm bảo đảm sự ổn định và an ninh không có sự can thiệp từ bên ngoài dưới bất kì hình thức hoặc biểu hiện nào”.\n\nNhận định sau đúng hay sai? Tuyên bố Băng Cốc đóng vai trò là Hiến chương của ASEAN từ khi thành lập đến năm 2008.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":82,"question":"Đọc đoạn tư liệu sau: “Nhận thức được sự tồn tại của các mối quan tâm lẫn nhau và các vấn đề chung giữa các nước Đông Nam Á và tin tưởng vào sự cần thiết phải tăng cường hơn nữa các mối quan hệ đoàn kết sẵn có trong khu vực; mong muốn xây dựng một nền tảng vững chắc cho hành động chung nhằm thúc đẩy hợp tác khu vực ở Đông Nam Á, các nước Đông Nam Á có trách nhiệm chính trong việc tăng cường ổn định kinh tế và xã hội của khu vực và bảo đảm sự phát triển đất nước hoà bình và tiến bộ, quyết tâm bảo đảm sự ổn định và an ninh không có sự can thiệp từ bên ngoài dưới bất kì hình thức hoặc biểu hiện nào”.\n\nNhận định sau đúng hay sai? Tuyên bố Băng Cốc là văn bản pháp lí để ASEAN hiện nay trở thành một liên minh quân sự.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":83,"question":"Đọc đoạn tư liệu sau: “Thứ ba, để thực hiện các tôn chỉ và mục đích của ASEAN, sẽ thiết lập bộ máy dưới đây: a) Hội nghị hàng năm của các Ngoại trưởng sẽ được tiến hành trên cơ sở luân phiên và được gọi là Hội nghị cấp Bộ trưởng ASEAN,... Thứ tư, Hiệp hội này mở rộng cho tất cả các quốc gia ở khu vực Đông Nam Á tán thành các tôn chỉ, nguyên tắc và mục đích nói trên tham gia”. (Tuyên bố Băng Cốc, ngày 8-8-1967)\n\nNhận định sau đúng hay sai? Đoạn tư liệu đề cập đến việc tổ chức hội nghị hằng năm của ngoại trưởng các nước Đông Nam Á.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":84,"question":"Đọc đoạn tư liệu sau: “Thứ ba, để thực hiện các tôn chỉ và mục đích của ASEAN, sẽ thiết lập bộ máy dưới đây: a) Hội nghị hàng năm của các Ngoại trưởng sẽ được tiến hành trên cơ sở luân phiên và được gọi là Hội nghị cấp Bộ trưởng ASEAN,... Thứ tư, Hiệp hội này mở rộng cho tất cả các quốc gia ở khu vực Đông Nam Á tán thành các tôn chỉ, nguyên tắc và mục đích nói trên tham gia”. (Tuyên bố Băng Cốc, ngày 8-8-1967)\n\nNhận định sau đúng hay sai? Nội dung Tuyên bố Băng Cốc cho thấy ASEAN sẵn sàng tiếp tục kết nạp thêm những thành viên khác trong khu vực.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":85,"question":"Đọc đoạn tư liệu sau: “Thứ ba, để thực hiện các tôn chỉ và mục đích của ASEAN, sẽ thiết lập bộ máy dưới đây: a) Hội nghị hàng năm của các Ngoại trưởng sẽ được tiến hành trên cơ sở luân phiên và được gọi là Hội nghị cấp Bộ trưởng ASEAN,... Thứ tư, Hiệp hội này mở rộng cho tất cả các quốc gia ở khu vực Đông Nam Á tán thành các tôn chỉ, nguyên tắc và mục đích nói trên tham gia”. (Tuyên bố Băng Cốc, ngày 8-8-1967)\n\nNhận định sau đúng hay sai? Tuyên bố Băng Cốc đóng vai trò là cơ sở pháp lí quan trọng nhất của ASEAN đến năm 2009.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":86,"question":"Đọc đoạn tư liệu sau: “Thứ ba, để thực hiện các tôn chỉ và mục đích của ASEAN, sẽ thiết lập bộ máy dưới đây: a) Hội nghị hàng năm của các Ngoại trưởng sẽ được tiến hành trên cơ sở luân phiên và được gọi là Hội nghị cấp Bộ trưởng ASEAN,... Thứ tư, Hiệp hội này mở rộng cho tất cả các quốc gia ở khu vực Đông Nam Á tán thành các tôn chỉ, nguyên tắc và mục đích nói trên tham gia”. (Tuyên bố Băng Cốc, ngày 8-8-1967)\n\nNhận định sau đúng hay sai? Hiện nay, Hội nghị Bộ trưởng Ngoại giao không còn là cơ chế hoạch định chính sách cao nhất của ASEAN.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":87,"question":"Đọc đoạn tư liệu sau: \"Quyết tâm sử dụng những cố gắng cần thiết bước đầu để bảo đảm việc công nhận và tôn trọng Đông Nam Á là một khu vực hoà bình, tự do và trung lập, không có sự can thiệp dưới bất kì hình thức và phương cách nào của các nước ngoài khu vực. Các nước Đông Nam Á cần phối hợp nỗ lực nhằm mở rộng các lĩnh vực hợp tác để góp phần tăng cường sức mạnh, tình đoàn kết, mối quan hệ gắn bó hơn nữa\". (ASEAN, Tuyên bố về khu vực hoà bình, tự do và trung lập, ngày 27-11-1971)\n\nNhận định sau đúng hay sai? Nội dung tư liệu đề cập sự kiện các nước Đông Nam Á thành lập khu vực hoà bình, tự do và trung lập.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":88,"question":"Đọc đoạn tư liệu sau: \"Quyết tâm sử dụng những cố gắng cần thiết bước đầu để bảo đảm việc công nhận và tôn trọng Đông Nam Á là một khu vực hoà bình, tự do và trung lập, không có sự can thiệp dưới bất kì hình thức và phương cách nào của các nước ngoài khu vực. Các nước Đông Nam Á cần phối hợp nỗ lực nhằm mở rộng các lĩnh vực hợp tác để góp phần tăng cường sức mạnh, tình đoàn kết, mối quan hệ gắn bó hơn nữa\". (ASEAN, Tuyên bố về khu vực hoà bình, tự do và trung lập, ngày 27-11-1971)\n\nNhận định sau đúng hay sai? Nội dung tuyên bố nhấn mạnh việc ASEAN không chấp nhận sự can thiệp của các nước ngoài khu vực.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":89,"question":"Đọc đoạn tư liệu sau: \"Quyết tâm sử dụng những cố gắng cần thiết bước đầu để bảo đảm việc công nhận và tôn trọng Đông Nam Á là một khu vực hoà bình, tự do và trung lập, không có sự can thiệp dưới bất kì hình thức và phương cách nào của các nước ngoài khu vực. Các nước Đông Nam Á cần phối hợp nỗ lực nhằm mở rộng các lĩnh vực hợp tác để góp phần tăng cường sức mạnh, tình đoàn kết, mối quan hệ gắn bó hơn nữa\". (ASEAN, Tuyên bố về khu vực hoà bình, tự do và trung lập, ngày 27-11-1971)\n\nNhận định sau đúng hay sai? Văn kiện trên có vai trò quyết định trong việc duy trì hoà bình, thống nhất và trung lập của Đông Nam Á.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":90,"question":"Đọc đoạn tư liệu sau: \"Quyết tâm sử dụng những cố gắng cần thiết bước đầu để bảo đảm việc công nhận và tôn trọng Đông Nam Á là một khu vực hoà bình, tự do và trung lập, không có sự can thiệp dưới bất kì hình thức và phương cách nào của các nước ngoài khu vực. Các nước Đông Nam Á cần phối hợp nỗ lực nhằm mở rộng các lĩnh vực hợp tác để góp phần tăng cường sức mạnh, tình đoàn kết, mối quan hệ gắn bó hơn nữa\". (ASEAN, Tuyên bố về khu vực hoà bình, tự do và trung lập, ngày 27-11-1971)\n\nNhận định sau đúng hay sai? Tuyên bố về khu vực hoà bình, tự do và trung lập vẫn có giá trị đối với tổ chức ASEAN ngày nay.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":91,"question":"Một trong những thách thức của Cộng đồng ASEAN là","options":{"A":"sự đa dạng của các nước thành viên về chế độ chính trị, tôn giáo.","B":"sự uy hiếp của các nước lớn ở khu vực Nam Á và Đông Á.","C":"thay đổi cấu trúc địa – văn hoá ở khu vực Ấn Độ Dương.","D":"khoảng cách về kinh tế giữa các nước ngày càng thu hẹp."},"answer":"A"},{"id":92,"question":"Những quốc gia nào sau đây là thành viên thứ 8 và thứ 9 của ASEAN?","options":{"A":"Việt Nam và Lào.","B":"Lào và Mi-an-ma.","C":"Cam-pu-chia và Bru-nây.","D":"Bru-nây và Mi-an-ma."},"answer":"B"},{"id":93,"question":"Nội dung nào sau đây không là triển vọng của Cộng đồng ASEAN?","options":{"A":"Sự vươn lên của khu vực Đông Nam Á.","B":"ASEAN có quan hệ rộng lớn với các đối tác bên ngoài.","C":"Vị thế của ASEAN ngày càng được nâng cao trên trường quốc tế.","D":"ASEAN trở thành một trong những trung tâm toàn cầu về quân sự."},"answer":"D"},{"id":94,"question":"Một trong những sự kiện đánh dấu bước ngoặt của ASEAN trong giai đoạn 1967-1976 là","options":{"A":"Hiệp ước Ba-li được kí kết.","B":"Hiến chương ASEAN được thông qua.","C":"ASEAN thành lập khu vực trung lập.","D":"Cộng đồng ASEAN được thành lập."},"answer":"A"},{"id":95,"question":"Ban Thư kí ASEAN có trụ sở tại","options":{"A":"Gia-các-ta (In-đô-nê-xi-a).","B":"Băng Cốc (Thái Lan).","C":"Hà Nội (Việt Nam).","D":"Ma-ni-la (Phi-líp-pin)."},"answer":"A"},{"id":96,"question":"Trong giai đoạn 1999-2015, ASEAN đạt được thành tựu quan trọng nào sau đây?","options":{"A":"Giải quyết xong mọi tranh chấp, xung đột trong khu vực.","B":"Phát triển số lượng thành viên từ 5 lên 10 nước.","C":"Ra Tuyên bố về khu vực hoà bình, tự do và trung lập.","D":"Hiến chương ASEAN được thông qua."},"answer":"D"},{"id":97,"question":"Đọc đoạn tư liệu sau: \"Không tham gia vào bất kì một chính sách hay hoạt động nào, kể cả việc sử dụng lãnh thổ của một nước, do bất kì một quốc gia thành viên ASEAN hay ngoài ASEAN hoặc đối tượng không phải là quốc gia tiến hành, đe doạ đến chủ quyền, toàn vẹn lãnh thổ hay sự ổn định chính trị và kinh tế của các quốc gia thành viên ASEAN; Tôn trọng sự khác biệt về văn hoá, ngôn ngữ và tôn giáo của người dân ASEAN đồng thời nhấn mạnh những giá trị chung trên tinh thần thống nhất trong đa dạng\". (Trích: Điều 2, Hiến chương ASEAN, ngày 20-11-2007)\n\nNhận định sau đúng hay sai? Nội dung tư liệu thể hiện hai mục tiêu cơ bản nhất và quan trọng nhất của ASEAN từ khi thành lập.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":98,"question":"Đọc đoạn tư liệu sau: \"Không tham gia vào bất kì một chính sách hay hoạt động nào, kể cả việc sử dụng lãnh thổ của một nước, do bất kì một quốc gia thành viên ASEAN hay ngoài ASEAN hoặc đối tượng không phải là quốc gia tiến hành, đe doạ đến chủ quyền, toàn vẹn lãnh thổ hay sự ổn định chính trị và kinh tế của các quốc gia thành viên ASEAN; Tôn trọng sự khác biệt về văn hoá, ngôn ngữ và tôn giáo của người dân ASEAN đồng thời nhấn mạnh những giá trị chung trên tinh thần thống nhất trong đa dạng\". (Trích: Điều 2, Hiến chương ASEAN, ngày 20-11-2007)\n\nNhận định sau đúng hay sai? Nội dung tư liệu thể hiện tinh thần \"thống nhất trong đa dạng\" của ASEAN và Đông Nam Á.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":99,"question":"Đọc đoạn tư liệu sau: \"Không tham gia vào bất kì một chính sách hay hoạt động nào, kể cả việc sử dụng lãnh thổ của một nước, do bất kì một quốc gia thành viên ASEAN hay ngoài ASEAN hoặc đối tượng không phải là quốc gia tiến hành, đe doạ đến chủ quyền, toàn vẹn lãnh thổ hay sự ổn định chính trị và kinh tế của các quốc gia thành viên ASEAN; Tôn trọng sự khác biệt về văn hoá, ngôn ngữ và tôn giáo của người dân ASEAN đồng thời nhấn mạnh những giá trị chung trên tinh thần thống nhất trong đa dạng\". (Trích: Điều 2, Hiến chương ASEAN, ngày 20-11-2007)\n\nNhận định sau đúng hay sai? Hiến chương ASEAN là văn kiện quan trọng của Hiệp hội các quốc gia Đông Nam Á.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":100,"question":"Đọc đoạn tư liệu sau: \"Không tham gia vào bất kì một chính sách hay hoạt động nào, kể cả việc sử dụng lãnh thổ của một nước, do bất kì một quốc gia thành viên ASEAN hay ngoài ASEAN hoặc đối tượng không phải là quốc gia tiến hành, đe doạ đến chủ quyền, toàn vẹn lãnh thổ hay sự ổn định chính trị và kinh tế của các quốc gia thành viên ASEAN; Tôn trọng sự khác biệt về văn hoá, ngôn ngữ và tôn giáo của người dân ASEAN đồng thời nhấn mạnh những giá trị chung trên tinh thần thống nhất trong đa dạng\". (Trích: Điều 2, Hiến chương ASEAN, ngày 20-11-2007)\n\nNhận định sau đúng hay sai? Hiến chương ASEAN tiếp tục là cơ sở pháp lí cho hoạt động của ASEAN hiện nay.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":101,"question":"Tầm nhìn ASEAN 2020 được thông qua năm 1997 tại hội nghị nào sau đây?","options":{"A":"Hội nghị cấp cao ASEAN lần thứ 5 tại Băng Cốc.","B":"Hội nghị thành lập tổ chức ASEAN tại Băng Cốc.","C":"Hội nghị cấp cao ASEAN lần thứ 37 tại Hà Nội.","D":"Hội nghị cấp cao ASEAN không chính thức lần thứ hai tại Ma-lai-xi-a."},"answer":"D"},{"id":102,"question":"Văn kiện nào sau đây thể hiện ý tưởng xây dựng Cộng đồng ASEAN?","options":{"A":"Tuyên bố Ba-li năm 1976.","B":"Tầm nhìn ASEAN 2025.","C":"Hiệp ước Ba-li năm 1976.","D":"Tầm nhìn ASEAN 2020."},"answer":"D"},{"id":103,"question":"Ý nào sau đây không đúng về Cộng đồng Chính trị – An ninh ASEAN (APSC)?","options":{"A":"APSC tạo ra một liên minh quân sự ở khu vực Đông Nam Á.","B":"APSC là khuôn khổ hợp tác chính trị - an ninh toàn diện.","C":"APSC hướng đến xây dựng một môi trường hoà bình và an ninh.","D":"APSC hoạt động dựa trên cơ sở tôn trọng các nguyên tắc cơ bản của ASEAN."},"answer":"A"},{"id":104,"question":"Một trong những nội dung chính của Cộng đồng Kinh tế ASEAN là","options":{"A":"phát triển nguồn nhân lực có tri thức cao.","B":"thúc đẩy chính sách cạnh tranh về kinh tế, bảo vệ người tiêu dùng.","C":"cùng nhau xây dựng các hàng rào thuế quan cho từng quốc gia.","D":"hướng tới xây dựng đồng tiền chung của Đông Nam Á."},"answer":"B"},{"id":105,"question":"Mục tiêu tổng quát của Cộng đồng ASEAN là xây dựng","options":{"A":"một tổ chức hợp tác liên chính phủ có liên kết sâu rộng, dựa trên cơ sở pháp lí là Hiến chương ASEAN.","B":"một tổ chức hợp tác liên chính phủ có liên kết sâu rộng theo mô hình siêu nhà nước.","C":"một chính phủ chung có liên kết sâu rộng, hướng tới một liên minh chính trị, quân sự.","D":"một tổ chức hợp tác liên minh liên kết sâu rộng dựa trên cơ sở là luật pháp của các nước thành viên."},"answer":"A"},{"id":106,"question":"Ngày 22-11-2015, các nhà lãnh đạo ASEAN đã nhóm họp tại Ma-lai-xi-a, chính thức thành lập","options":{"A":"Cộng đồng ASEAN.","B":"Hội đồng các nước ASEAN.","C":"Liên minh ASEAN.","D":"Uỷ ban ASEAN."},"answer":"A"},{"id":107,"question":"Một trong những nội dung chính hoạt động của Cộng đồng Văn hoá - Xã hội ASEAN là xây dựng","options":{"A":"tinh thần đoàn kết và thống nhất bền lâu giữa các quốc gia và dân tộc ASEAN.","B":"liên kết về văn hoá và bản sắc giữa khu vực ASEAN với bên ngoài.","C":"cơ sở hạ tầng cho các quốc gia thành viên trong khu vực.","D":"chính sách an sinh xã hội, xoá đói giảm nghèo cho từng quốc gia."},"answer":"A"},{"id":108,"question":"Đọc đoạn tư liệu sau: \"Liên hợp quốc đánh giá cao sự tham dự và cam kết vững chắc của ASEAN đối với chủ nghĩa đa phương và hợp tác khu vực. ASEAN có vai trò cốt lõi trong việc thúc đẩy nhân quyền, các quyền cơ bản và sự tham dự chính trị rộng rãi như các thành tố để xây dựng các xã hội thực sự hoà bình, ổn định. Và ASEAN cũng đóng vai trò nòng cốt trong sự phát triển của một nền kinh tế toàn cầu vững mạnh\".\n\nNhận định sau đúng hay sai? ASEAN quyết định sự phát triển của kinh tế toàn cầu.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":109,"question":"Đọc đoạn tư liệu sau: \"Liên hợp quốc đánh giá cao sự tham dự và cam kết vững chắc của ASEAN đối với chủ nghĩa đa phương và hợp tác khu vực. ASEAN có vai trò cốt lõi trong việc thúc đẩy nhân quyền, các quyền cơ bản và sự tham dự chính trị rộng rãi như các thành tố để xây dựng các xã hội thực sự hoà bình, ổn định. Và ASEAN cũng đóng vai trò nòng cốt trong sự phát triển của một nền kinh tế toàn cầu vững mạnh\".\n\nNhận định sau đúng hay sai? ASEAN là tổ chức khu vực thành công nhất thế giới.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":110,"question":"Đọc đoạn tư liệu sau: \"Liên hợp quốc đánh giá cao sự tham dự và cam kết vững chắc của ASEAN đối với chủ nghĩa đa phương và hợp tác khu vực. ASEAN có vai trò cốt lõi trong việc thúc đẩy nhân quyền, các quyền cơ bản và sự tham dự chính trị rộng rãi như các thành tố để xây dựng các xã hội thực sự hoà bình, ổn định. Và ASEAN cũng đóng vai trò nòng cốt trong sự phát triển của một nền kinh tế toàn cầu vững mạnh\".\n\nNhận định sau đúng hay sai? ASEAN là tổ chức hợp tác chính trị, quân sự toàn cầu.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":111,"question":"Đọc đoạn tư liệu sau: \"Liên hợp quốc đánh giá cao sự tham dự và cam kết vững chắc của ASEAN đối với chủ nghĩa đa phương và hợp tác khu vực. ASEAN có vai trò cốt lõi trong việc thúc đẩy nhân quyền, các quyền cơ bản và sự tham dự chính trị rộng rãi như các thành tố để xây dựng các xã hội thực sự hoà bình, ổn định. Và ASEAN cũng đóng vai trò nòng cốt trong sự phát triển của một nền kinh tế toàn cầu vững mạnh\".\n\nNhận định sau đúng hay sai? ASEAN đóng vai trò quan trọng đối với nền kinh tế toàn cầu.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":112,"question":"Hiệp hội các quốc gia Đông Nam Á (ASEAN) ra đời trong hoàn cảnh nào sau đây?","options":{"A":"Xu thế hòa hoãn Đông - Tây trở thành chủ đạo trên thế giới.","B":"Thế giới và khu vực đang có những chuyển biến quan trọng.","C":"Tất cả các nước khu vực Đông Nam Á đều giành được độc lập.","D":"Chiến tranh lạnh kết thúc, các dân tộc đang hòa hợp, hòa giải."},"answer":"B"},{"id":113,"question":"Nội dung nào phản ánh không đúng vai trò của tổ chức ASEAN đối với việc bảo vệ hòa bình, ổn định ở khu vực và Biển Đông?","options":{"A":"Đoàn kết nhất trí và thể hiện vai trò, tinh thần trách nhiệm cao.","B":"Lên án, phản đối hành động xâm phạm chủ quyền các quốc gia.","C":"Khẳng định các nguyên tắc của luật pháp quốc tế và ASEAN.","D":"Dùng biện pháp quân sự để bảo vệ hòa bình, ổn định ở khu vực."},"answer":"D"},{"id":114,"question":"Một trong những khó khăn mà các nước ASEAN phải đương đầu sau khi thành lập là","options":{"A":"khủng hoảng tài chính.","B":"xu thế hợp tác khu vực.","C":"nhiều dịch bệnh diễn ra.","D":"xuất phát điểm rất thấp."},"answer":"D"},{"id":115,"question":"Nội dung nào không phản ánh đúng những cơ hội khi Việt Nam gia nhập tổ chức ASEAN?","options":{"A":"Đẩy mạnh được công nghiệp hóa, hiện đại hóa đất nước.","B":"Tranh thủ viện trợ để giải quyết khó khăn ở trong nước.","C":"Thu hút vốn đầu tư và khoa học - công nghệ tiên tiến.","D":"Tăng cường giao lưu về mọi mặt và mở rộng thị trường."},"answer":"B"},{"id":116,"question":"Quốc gia nào là thành viên thứ 10 của ASEAN?","options":{"A":"Cam-pu-chia.","B":"Mi-an-ma.","C":"Việt Nam.","D":"Thái Lan."},"answer":"A"},{"id":117,"question":"Tổ chức hợp tác nào mang tính khu vực trên thế giới đã cổ vũ các nước Đông Nam Á tìm cách liên kết lại với nhau?","options":{"A":"Diễn đàn hợp tác kinh tế Á - Âu.","B":"Diễn đàn kinh tế Thái Bình Dương.","C":"Cộng đồng kinh tế châu Âu.","D":"Cộng đồng các quốc gia độc lập."},"answer":"C"},{"id":118,"question":"Đâu là nguyên nhân Nhật Bản điều chỉnh chính sách đối ngoại đặt trọng tâm vào quan hệ với Đông Nam Á và ASEAN từ những năm 90 của thế kỉ XX?","options":{"A":"Khu vực đông dân, giàu tài nguyên.","B":"Đây đã là xu thế chung của thế giới.","C":"Cạnh tranh sức ảnh hưởng với Nga.","D":"Để xây dựng một số căn cứ quân sự."},"answer":"A"},{"id":119,"question":"Sự kiện Việt Nam gia nhập ASEAN (1995) đã tác động như thế nào đến sự phát triển của tổ chức này?","options":{"A":"Củng cố nền độc lập mới ở Đông Nam Á.","B":"Đập tan âm mưu nô dịch các nước ASEAN.","C":"Đẩy nhanh quá trình phát triển của ASEAN.","D":"Thúc đẩy nhanh quá trình phi thực dân hóa."},"answer":"C"},{"id":120,"question":"Nguyên nhân chủ yếu dẫn đến quan hệ đối thoại, hợp tác và hội nhập giữa tổ chức ASEAN với ba nước Đông Dương từ đầu những năm 90 của thế kỉ XX là","options":{"A":"do đây là xu thế chung của thế giới.","B":"vấn đề Cam-pu-chia được giải quyết.","C":"tác động của xu thế toàn cầu hóa.","D":"do cuộc Chiến tranh lạnh chấm dứt."},"answer":"B"},{"id":121,"question":"Một trong những nguyên nhân thúc đẩy sự ra đời của tổ chức ASEAN là","options":{"A":"thành lập một liên minh quân sự.","B":"tiến tới thành lập nước liên bang.","C":"hợp tác để cùng nhau phát triển.","D":"tổ chức lại trật tự khu vực châu Á."},"answer":"C"},{"id":122,"question":"Từ sự phát triển kinh tế của Xin-ga-po ở những thập kỉ cuối thế kỉ XX, Việt Nam có thể rút ra bài học kinh nghiệm gì để đẩy mạnh công nghiệp hóa, hiện đại hóa đất nước hiện nay?","options":{"A":"Áp dụng thành tựu khoa học - kĩ thuật hiện đại.","B":"Chú trọng phát triển ngành công nghệ phần mềm.","C":"Tập trung đầu tư xây dựng cơ sở hạ tầng kinh tế.","D":"Coi trọng khai thác nguồn tài nguyên thiên nhiên."},"answer":"A"},{"id":123,"question":"Một trong những thuận lợi cơ bản mà các nước ASEAN có được sau Chiến tranh thế giới thứ hai (1945) là","options":{"A":"thiết lập quan hệ với Liên Xô.","B":"khôi phục quan hệ với Nhật.","C":"đã cơ bản giành được độc lập.","D":"nhận viện trợ kinh tế của Mỹ."},"answer":"C"},{"id":124,"question":"Một trong những nội dung hợp tác chủ yếu của các nước ASEAN là","options":{"A":"thể thao.","B":"quân sự.","C":"kinh tế.","D":"đối ngoại."},"answer":"C"},{"id":125,"question":"Đâu là nguyên nhân đã thúc đẩy Việt Nam gia nhập tổ chức ASEAN?","options":{"A":"Tất cả các nước Đông Nam Á đã gia nhập vào tổ chức ASEAN.","B":"Quan hệ ASEAN và Việt Nam chuyển sang đối thoại, hợp tác.","C":"Tổ chức ASEAN phù hợp với yêu cầu phát triển của Việt Nam.","D":"Đây là nội dung trong chính sách đối ngoại được Liên Xô đồng ý."},"answer":"B"},{"id":126,"question":"Trong quá trình phát triển của ASEAN, giai đoạn từ 1967 - 1976 có đặc điểm là gì?","options":{"A":"Phát triển rất nhanh.","B":"Nền kinh tế xuất khẩu.","C":"Tránh đối đầu quân sự.","D":"Xây dựng nền móng."},"answer":"D"},{"id":127,"question":"Trong Chiến tranh thế giới thứ hai (1939 - 1945), Đông Nam Á là thuộc địa của","options":{"A":"Pháp.","B":"Mỹ.","C":"Nhật.","D":"Anh."},"answer":"C"},{"id":128,"question":"Một trong những mục tiêu của tổ chức ASEAN khi thành lập là","options":{"A":"củng cố quan hệ chính trị, giúp đỡ Đông Dương giành lại độc lập.","B":"tăng cường quan hệ hợp tác mọi mặt nhằm phát triển kinh tế - xã hội.","C":"phát triển kinh tế và văn hóa thông qua những nỗ lực hợp tác chung.","D":"giải quyết vấn đề xung đột Cam-pu-chia và tranh chấp ở Biển Đông."},"answer":"C"},{"id":129,"question":"Văn kiện nào đã nêu rõ mục đích thành lập của tổ chức ASEAN?","options":{"A":"Tuyên bố ASEAN.","B":"Hiệp định Pa-ri.","C":"Hiệp định Giơ-ne-vơ.","D":"Tuyên bố La Hay."},"answer":"A"},{"id":130,"question":"Cơ hội lớn nhất khi Việt Nam gia nhập tổ chức ASEAN là","options":{"A":"khai thác vốn đầu tư, khoa học - công nghệ.","B":"giao lưu, học hỏi về văn hóa, giáo dục, y tế.","C":"được mở rộng thị trường trao đổi hàng hóa.","D":"tiếp thu những kinh nghiệm quản lý sản xuất."},"answer":"A"},{"id":131,"question":"Sự kiện nào sau đây đã đưa ASEAN từ tổ chức non yếu trở nên hoàn thiện, vị thế được nâng cao trên thế giới?","options":{"A":"Thông qua Tuyên bố ASEAN.","B":"Hiệp định Giơ-ne-vơ.","C":"Thông cáo Thượng Hải.","D":"Hiệp ước Ba-li được kí kết."},"answer":"D"},{"id":132,"question":"Nội dung nào sau đây là khó khăn trong quá trình mở rộng thành viên của ASEAN từ sau khi Chiến tranh lạnh kết thúc (1989)?","options":{"A":"Sự khác biệt về thể chế chính trị.","B":"Tác động từ các nước châu Âu.","C":"Mâu thuẫn gay gắt về tôn giáo.","D":"Tác động từ chủ nghĩa khủng bố."},"answer":"A"},{"id":133,"question":"Ba nước ở Đông Nam Á tuyên bố độc lập vào năm 1945 là","options":{"A":"In-đô-nê-xi-a, Việt Nam, Lào.","B":"Xin-ga-po, In-đô-nê-xi-a, Việt Nam.","C":"Việt Nam, Lào, Cam-pu-chia.","D":"In-đô-nê-xi-a, Việt Nam, Ma-lai-xi-a."},"answer":"A"},{"id":134,"question":"Vì sao trong giai đoạn 1979 - 1991 quan hệ giữa Việt Nam và ASEAN là đối đầu, căng thẳng?","options":{"A":"Vấn đề Cam-pu-chia.","B":"Khủng hoảng năng lượng.","C":"Tranh chấp biên giới.","D":"Xung đột ở Biển Đông."},"answer":"A"},{"id":135,"question":"Đâu là nhận xét đúng về vai trò của tổ chức ASEAN trên trường quốc tế?","options":{"A":"Tổ chức liên kết kinh tế, thương mại, tài chính lớn nhất của châu Á.","B":"Liên minh hợp tác toàn diện, hiệu quả của khu vực Đông Nam Á.","C":"Liên minh chính trị - kinh tế chiến lược của khu vực Đông Nam Á.","D":"Diễn đàn hợp tác kinh tế đa phương ở châu Á - Thái Bình Dương."},"answer":"C"},{"id":136,"question":"Đọc đoạn tư liệu sau đây: “Sau khi giành được độc lập, các quốc gia Đông Nam Á bước vào thời kỳ phát triển kinh tế, yêu cầu hợp tác khu vực trở nên cấp thiết. Xu thế khu vực hóa trên thế giới những năm 50, 60 của thế kỷ XX cổ vũ các nước Đông Nam Á tìm cách liên kết với nhau. Mặt khác, sau Chiến tranh thế giới thứ hai, các cường quốc bên ngoài đã có sự can dự vào khu vực Đông Nam Á. Sự xuất hiện những nhân tố mới này đã trở thành cơ sở để thành lập nên một tổ chức nhằm thúc đẩy hợp tác, tương trợ lẫn nhau giữa các quốc gia ở Đông Nam Á”.\n\nNhận định sau đúng hay sai? Tư liệu nói về mục đích hoạt động và quá trình thành lập tổ chức ASEAN.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":137,"question":"Đọc đoạn tư liệu sau đây: “Sau khi giành được độc lập, các quốc gia Đông Nam Á bước vào thời kỳ phát triển kinh tế, yêu cầu hợp tác khu vực trở nên cấp thiết. Xu thế khu vực hóa trên thế giới những năm 50, 60 của thế kỷ XX cổ vũ các nước Đông Nam Á tìm cách liên kết với nhau. Mặt khác, sau Chiến tranh thế giới thứ hai, các cường quốc bên ngoài đã có sự can dự vào khu vực Đông Nam Á. Sự xuất hiện những nhân tố mới này đã trở thành cơ sở để thành lập nên một tổ chức nhằm thúc đẩy hợp tác, tương trợ lẫn nhau giữa các quốc gia ở Đông Nam Á”.\n\nNhận định sau đúng hay sai? Tổ chức ASEAN ban đầu gồm có 5 nước, trong đó Thái Lan là nước lãnh đạo.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":138,"question":"Đọc đoạn tư liệu sau đây: “Sau khi giành được độc lập, các quốc gia Đông Nam Á bước vào thời kỳ phát triển kinh tế, yêu cầu hợp tác khu vực trở nên cấp thiết. Xu thế khu vực hóa trên thế giới những năm 50, 60 của thế kỷ XX cổ vũ các nước Đông Nam Á tìm cách liên kết với nhau. Mặt khác, sau Chiến tranh thế giới thứ hai, các cường quốc bên ngoài đã có sự can dự vào khu vực Đông Nam Á. Sự xuất hiện những nhân tố mới này đã trở thành cơ sở để thành lập nên một tổ chức nhằm thúc đẩy hợp tác, tương trợ lẫn nhau giữa các quốc gia ở Đông Nam Á”.\n\nNhận định sau đúng hay sai? ASEAN ra đời trong bối cảnh các cường quốc can thiệp vào Đông Nam Á.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":139,"question":"Đọc đoạn tư liệu sau đây: “Sau khi giành được độc lập, các quốc gia Đông Nam Á bước vào thời kỳ phát triển kinh tế, yêu cầu hợp tác khu vực trở nên cấp thiết. Xu thế khu vực hóa trên thế giới những năm 50, 60 của thế kỷ XX cổ vũ các nước Đông Nam Á tìm cách liên kết với nhau. Mặt khác, sau Chiến tranh thế giới thứ hai, các cường quốc bên ngoài đã có sự can dự vào khu vực Đông Nam Á. Sự xuất hiện những nhân tố mới này đã trở thành cơ sở để thành lập nên một tổ chức nhằm thúc đẩy hợp tác, tương trợ lẫn nhau giữa các quốc gia ở Đông Nam Á”.\n\nNhận định sau đúng hay sai? ASEAN đã trở thành tổ chức bao gồm tất cả các quốc gia ở Đông Nam Á.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":140,"question":"Đọc đoạn tư liệu sau đây: Tư liệu 1: “Trong cuốn sách Kỳ diệu ASEAN - Chất xúc tác cho hòa bình (The ASEAN miracle, A Catalyst for Peace), xuất bản vào dịp kỷ niệm 50 năm thành lập tổ chức ASEAN (1967-2017), các tác giả cho rằng thành công của ASEAN là một điều kỳ diệu và thế giới sẽ trở nên tốt đẹp hơn khi các khu vực đang phát triển khác noi gương sự thành công của ASEAN để tạo ra hòa bình, thịnh vượng.” Tư liệu 2: “Sự kiện Việt Nam trở thành thành viên thứ bảy của ASEAN là dấu mốc quan trọng trong sự phát triển của ASEAN. Đây không chỉ là sự tăng thêm về số lượng thành viên mà còn đẩy nhanh quá trình thực hiện mục tiêu xây dựng ASEAN trở thành \"ngôi nhà chung\" của các quốc gia Đông Nam Á.”\n\nNhận định sau đúng hay sai? Tư liệu 1 khẳng định ASEAN là một thành công của hợp tác khu vực trên thế giới.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":141,"question":"Đọc đoạn tư liệu sau đây: Tư liệu 1: “Trong cuốn sách Kỳ diệu ASEAN - Chất xúc tác cho hòa bình (The ASEAN miracle, A Catalyst for Peace), xuất bản vào dịp kỷ niệm 50 năm thành lập tổ chức ASEAN (1967-2017), các tác giả cho rằng thành công của ASEAN là một điều kỳ diệu và thế giới sẽ trở nên tốt đẹp hơn khi các khu vực đang phát triển khác noi gương sự thành công của ASEAN để tạo ra hòa bình, thịnh vượng.” Tư liệu 2: “Sự kiện Việt Nam trở thành thành viên thứ bảy của ASEAN là dấu mốc quan trọng trong sự phát triển của ASEAN. Đây không chỉ là sự tăng thêm về số lượng thành viên mà còn đẩy nhanh quá trình thực hiện mục tiêu xây dựng ASEAN trở thành \"ngôi nhà chung\" của các quốc gia Đông Nam Á.”\n\nNhận định sau đúng hay sai? ASEAN góp phần quan trọng tạo dựng hòa bình, an ninh, ổn định ở Đông Nam Á.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":142,"question":"Đọc đoạn tư liệu sau đây: Tư liệu 1: “Trong cuốn sách Kỳ diệu ASEAN - Chất xúc tác cho hòa bình (The ASEAN miracle, A Catalyst for Peace), xuất bản vào dịp kỷ niệm 50 năm thành lập tổ chức ASEAN (1967-2017), các tác giả cho rằng thành công của ASEAN là một điều kỳ diệu và thế giới sẽ trở nên tốt đẹp hơn khi các khu vực đang phát triển khác noi gương sự thành công của ASEAN để tạo ra hòa bình, thịnh vượng.” Tư liệu 2: “Sự kiện Việt Nam trở thành thành viên thứ bảy của ASEAN là dấu mốc quan trọng trong sự phát triển của ASEAN. Đây không chỉ là sự tăng thêm về số lượng thành viên mà còn đẩy nhanh quá trình thực hiện mục tiêu xây dựng ASEAN trở thành \"ngôi nhà chung\" của các quốc gia Đông Nam Á.”\n\nNhận định sau đúng hay sai? Tư liệu 2 khẳng định khi Việt Nam gia nhập, ASEAN đã thành tổ chức toàn khu vực.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":143,"question":"Đọc đoạn tư liệu sau đây: Tư liệu 1: “Trong cuốn sách Kỳ diệu ASEAN - Chất xúc tác cho hòa bình (The ASEAN miracle, A Catalyst for Peace), xuất bản vào dịp kỷ niệm 50 năm thành lập tổ chức ASEAN (1967-2017), các tác giả cho rằng thành công của ASEAN là một điều kỳ diệu và thế giới sẽ trở nên tốt đẹp hơn khi các khu vực đang phát triển khác noi gương sự thành công của ASEAN để tạo ra hòa bình, thịnh vượng.” Tư liệu 2: “Sự kiện Việt Nam trở thành thành viên thứ bảy của ASEAN là dấu mốc quan trọng trong sự phát triển của ASEAN. Đây không chỉ là sự tăng thêm về số lượng thành viên mà còn đẩy nhanh quá trình thực hiện mục tiêu xây dựng ASEAN trở thành \"ngôi nhà chung\" của các quốc gia Đông Nam Á.”\n\nNhận định sau đúng hay sai? Việc Việt Nam gia nhập đã đánh dấu ASEAN trở thành tổ chức khu vực phát triển.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":144,"question":"Đọc đoạn tư liệu sau đây: “Tôn chỉ và mục đích của ASEAN: Thúc đẩy sự tăng trưởng kinh tế, tiến bộ xã hội và phát triển văn hóa trong khu vực thông qua các nỗ lực chung trên tinh thần bình đẳng và hợp tác nhằm tăng cường cơ sở cho một Cộng đồng các quốc gia Đông Nam Á hòa bình và thịnh vượng; Thúc đẩy hòa bình và ổn định khu vực bằng việc tôn trọng công lý và nguyên tắc luật pháp trong quan hệ giữa các quốc gia trong vùng và tuân thủ các nguyên tắc của Hiến chương Liên hợp quốc; Thúc đẩy sự cộng tác tích cực và giúp đỡ lẫn nhau trong các vấn đề cùng quan tâm ở các lĩnh vực kinh tế, xã hội, văn hóa, khoa học - kỹ thuật và hành chính,...”\n\nNhận định sau đúng hay sai? ASEAN hoạt động dựa trên tôn chỉ và mục đích của Hiến chương Liên hợp quốc.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":145,"question":"Đọc đoạn tư liệu sau đây: “Tôn chỉ và mục đích của ASEAN: Thúc đẩy sự tăng trưởng kinh tế, tiến bộ xã hội và phát triển văn hóa trong khu vực thông qua các nỗ lực chung trên tinh thần bình đẳng và hợp tác nhằm tăng cường cơ sở cho một Cộng đồng các quốc gia Đông Nam Á hòa bình và thịnh vượng; Thúc đẩy hòa bình và ổn định khu vực bằng việc tôn trọng công lý và nguyên tắc luật pháp trong quan hệ giữa các quốc gia trong vùng và tuân thủ các nguyên tắc của Hiến chương Liên hợp quốc; Thúc đẩy sự cộng tác tích cực và giúp đỡ lẫn nhau trong các vấn đề cùng quan tâm ở các lĩnh vực kinh tế, xã hội, văn hóa, khoa học - kỹ thuật và hành chính,...”\n\nNhận định sau đúng hay sai? ASEAN là tổ chức liên minh khu vực hợp tác ban đầu về kinh tế, văn hóa, xã hội.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":146,"question":"Đọc đoạn tư liệu sau đây: “Tôn chỉ và mục đích của ASEAN: Thúc đẩy sự tăng trưởng kinh tế, tiến bộ xã hội và phát triển văn hóa trong khu vực thông qua các nỗ lực chung trên tinh thần bình đẳng và hợp tác nhằm tăng cường cơ sở cho một Cộng đồng các quốc gia Đông Nam Á hòa bình và thịnh vượng; Thúc đẩy hòa bình và ổn định khu vực bằng việc tôn trọng công lý và nguyên tắc luật pháp trong quan hệ giữa các quốc gia trong vùng và tuân thủ các nguyên tắc của Hiến chương Liên hợp quốc; Thúc đẩy sự cộng tác tích cực và giúp đỡ lẫn nhau trong các vấn đề cùng quan tâm ở các lĩnh vực kinh tế, xã hội, văn hóa, khoa học - kỹ thuật và hành chính,...”\n\nNhận định sau đúng hay sai? Tư liệu khẳng định tôn chỉ thành lập và mục đích hoạt động của tổ chức ASEAN.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":147,"question":"Đọc đoạn tư liệu sau đây: “Tôn chỉ và mục đích của ASEAN: Thúc đẩy sự tăng trưởng kinh tế, tiến bộ xã hội và phát triển văn hóa trong khu vực thông qua các nỗ lực chung trên tinh thần bình đẳng và hợp tác nhằm tăng cường cơ sở cho một Cộng đồng các quốc gia Đông Nam Á hòa bình và thịnh vượng; Thúc đẩy hòa bình và ổn định khu vực bằng việc tôn trọng công lý và nguyên tắc luật pháp trong quan hệ giữa các quốc gia trong vùng và tuân thủ các nguyên tắc của Hiến chương Liên hợp quốc; Thúc đẩy sự cộng tác tích cực và giúp đỡ lẫn nhau trong các vấn đề cùng quan tâm ở các lĩnh vực kinh tế, xã hội, văn hóa, khoa học - kỹ thuật và hành chính,...”\n\nNhận định sau đúng hay sai? ASEAN ra đời đã tạo ra cơ chế thúc đẩy hòa bình và ổn định các vấn đề ở châu Á.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":148,"question":"Đọc đoạn tư liệu sau đây: “Giai đoạn 1999 - 2015: ASEAN chú trọng củng cố sự đoàn kết trong tổ chức, đóng vai trò trung tâm trong quá trình liên kết khu vực Đông Nam Á. Sau khi thông qua Hiến chương ASEAN (2007), ASEAN thông qua lộ trình xây dựng Cộng đồng ASEAN với ba trụ cột (2009): Cộng đồng Chính trị - An ninh ASEAN (APSC), Cộng đồng Kinh tế ASEAN (AEC) và Cộng đồng Văn hóa - Xã hội ASEAN (ASCC). Giai đoạn 2015 - nay: năm 2015, Cộng đồng ASEAN được thành lập, ASEAN tập trung thực hiện các mục tiêu của cộng đồng, thúc đẩy hợp tác nội khối trên cơ sở ba trụ cột APSC, AEC và ASCC. ASEAN chủ động mở rộng quan hệ hợp tác với các chủ thể bên ngoài, tiếp tục phát huy vị thế trung tâm tại các diễn đàn hợp tác trong khu vực châu Á - Thái Bình Dương nhằm đảm bảo hòa bình và phát triển.”\n\nNhận định sau đúng hay sai? Năm 2007, Cộng đồng ASEAN được thành lập và hoạt động dựa trên ba trụ cột.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":149,"question":"Đọc đoạn tư liệu sau đây: “Giai đoạn 1999 - 2015: ASEAN chú trọng củng cố sự đoàn kết trong tổ chức, đóng vai trò trung tâm trong quá trình liên kết khu vực Đông Nam Á. Sau khi thông qua Hiến chương ASEAN (2007), ASEAN thông qua lộ trình xây dựng Cộng đồng ASEAN với ba trụ cột (2009): Cộng đồng Chính trị - An ninh ASEAN (APSC), Cộng đồng Kinh tế ASEAN (AEC) và Cộng đồng Văn hóa - Xã hội ASEAN (ASCC). Giai đoạn 2015 - nay: năm 2015, Cộng đồng ASEAN được thành lập, ASEAN tập trung thực hiện các mục tiêu của cộng đồng, thúc đẩy hợp tác nội khối trên cơ sở ba trụ cột APSC, AEC và ASCC. ASEAN chủ động mở rộng quan hệ hợp tác với các chủ thể bên ngoài, tiếp tục phát huy vị thế trung tâm tại các diễn đàn hợp tác trong khu vực châu Á - Thái Bình Dương nhằm đảm bảo hòa bình và phát triển.”\n\nNhận định sau đúng hay sai? Khi mới thành lập, ASEAN hợp tác trên 3 trụ cột chính là APSC, AEC và ASCC.","options":{"A":"Đúng","B":"Sai"},"answer":"B"},{"id":150,"question":"Đọc đoạn tư liệu sau đây: “Giai đoạn 1999 - 2015: ASEAN chú trọng củng cố sự đoàn kết trong tổ chức, đóng vai trò trung tâm trong quá trình liên kết khu vực Đông Nam Á. Sau khi thông qua Hiến chương ASEAN (2007), ASEAN thông qua lộ trình xây dựng Cộng đồng ASEAN với ba trụ cột (2009): Cộng đồng Chính trị - An ninh ASEAN (APSC), Cộng đồng Kinh tế ASEAN (AEC) và Cộng đồng Văn hóa - Xã hội ASEAN (ASCC). Giai đoạn 2015 - nay: năm 2015, Cộng đồng ASEAN được thành lập, ASEAN tập trung thực hiện các mục tiêu của cộng đồng, thúc đẩy hợp tác nội khối trên cơ sở ba trụ cột APSC, AEC và ASCC. ASEAN chủ động mở rộng quan hệ hợp tác với các chủ thể bên ngoài, tiếp tục phát huy vị thế trung tâm tại các diễn đàn hợp tác trong khu vực châu Á - Thái Bình Dương nhằm đảm bảo hòa bình và phát triển.”\n\nNhận định sau đúng hay sai? ASEAN trải qua nhiều giai đoạn phát triển với sự hợp tác ngày càng chặt chẽ hơn.","options":{"A":"Đúng","B":"Sai"},"answer":"A"},{"id":151,"question":"Đọc đoạn tư liệu sau đây: “Giai đoạn 1999 - 2015: ASEAN chú trọng củng cố sự đoàn kết trong tổ chức, đóng vai trò trung tâm trong quá trình liên kết khu vực Đông Nam Á. Sau khi thông qua Hiến chương ASEAN (2007), ASEAN thông qua lộ trình xây dựng Cộng đồng ASEAN với ba trụ cột (2009): Cộng đồng Chính trị - An ninh ASEAN (APSC), Cộng đồng Kinh tế ASEAN (AEC) và Cộng đồng Văn hóa - Xã hội ASEAN (ASCC). Giai đoạn 2015 - nay: năm 2015, Cộng đồng ASEAN được thành lập, ASEAN tập trung thực hiện các mục tiêu của cộng đồng, thúc đẩy hợp tác nội khối trên cơ sở ba trụ cột APSC, AEC và ASCC. ASEAN chủ động mở rộng quan hệ hợp tác với các chủ thể bên ngoài, tiếp tục phát huy vị thế trung tâm tại các diễn đàn hợp tác trong khu vực châu Á - Thái Bình Dương nhằm đảm bảo hòa bình và phát triển.”\n\nNhận định sau đúng hay sai? Tại các diễn đàn hợp tác châu Á - Thái Bình Dương, ASEAN có vị thế trung tâm.","options":{"A":"Đúng","B":"Sai"},"answer":"A"}];
